#!/usr/bin/env node
// Source extraction for the website (OSS_SPEC §11.2). Reads every fact the
// site shows from the repository and writes src/generated/sourceData.ts,
// which is gitignored and regenerated by `dev` and `build`. Rendered doc
// bodies are a separate export so the client bundle tree-shakes them away and
// hydrates from the prerendered HTML instead.
//
// Released facts (version, CLI commands and flags, capabilities, TLS modes,
// defaults, changelog) come from the latest v* tag when one exists, so the
// site describes what users can install. Docs and examples come from the
// working tree so documentation fixes ship immediately (§10.4).
//
// Fails loudly: a missing marker, command table or doc heading exits
// non-zero instead of emitting stale or empty data.

import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { Marked } from "marked";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "../..");
const OUT = resolve(__dirname, "../src/generated/sourceData.ts");
const REPO = "https://github.com/niclaslindstedt/storage";
const BASE = "/storage/";

function fail(message) {
  process.stderr.write(`extract-source-data: ${message}\n`);
  process.exit(1);
}

function git(...args) {
  try {
    return execFileSync("git", args, { cwd: ROOT, encoding: "utf8" }).trim();
  } catch {
    return "";
  }
}

const tag = git("tag", "-l", "v*", "--sort=-v:refname").split("\n")[0] || null;

/** A released source file: at the latest tag, else the working tree. */
function released(path) {
  if (tag) {
    const text = git("show", `${tag}:${path}`);
    if (text) return text;
  }
  const full = join(ROOT, path);
  if (!existsSync(full)) fail(`missing ${path}`);
  return readFileSync(full, "utf8");
}

function working(path) {
  const full = join(ROOT, path);
  if (!existsSync(full)) fail(`missing ${path}`);
  return readFileSync(full, "utf8");
}

/** Import a dependency-free TypeScript module (Node strips the types). */
async function importTs(path, source) {
  if (/^import\s/m.test(source))
    fail(`${path} gained imports; the extractor loads it standalone`);
  const dir = mkdtempSync(join(tmpdir(), "storage-extract-"));
  try {
    const file = join(dir, path.split("/").pop());
    writeFileSync(file, source);
    return await import(pathToFileURL(file).href);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/** ISO date of the last commit touching `path`, else of HEAD. */
function lastModified(path) {
  return (
    git("log", "-1", "--format=%cI", "--", path) ||
    git("log", "-1", "--format=%cI") ||
    fail(`no git history for ${path}`)
  );
}

function firstPublished(path) {
  return (
    git("log", "--diff-filter=A", "--follow", "--format=%cI", "--", path)
      .split("\n")
      .filter(Boolean)
      .at(-1) || lastModified(path)
  );
}

// ---------------------------------------------------------------- facts

const serverPkg = JSON.parse(released("packages/server/package.json"));
if (!serverPkg.version) fail("packages/server/package.json has no version");

const spec = await importTs(
  "packages/server/src/cli/spec.ts",
  released("packages/server/src/cli/spec.ts"),
);
for (const key of ["COMMANDS", "GLOBAL_FLAGS", "SERVER_FLAGS", "BIN"])
  if (!spec[key]) fail(`cli/spec.ts no longer exports ${key}`);
const commands = spec.COMMANDS.map((c) => ({
  name: c.name,
  summary: c.summary,
  usage: c.usage,
  examples: c.examples,
}));
for (const required of ["serve", "setup", "pair", "test-server"])
  if (!commands.some((c) => c.name === required))
    fail(`command "${required}" disappeared from cli/spec.ts`);
const settings = spec.SERVER_FLAGS.filter((f) => f.env).map((f) => ({
  flag: `--${f.name}`,
  env: f.env,
  config: f.config ?? null,
  default: f.default ?? null,
  description: f.description,
}));
if (settings.length < 5) fail("SERVER_FLAGS lost its environment variables");

const config = await importTs(
  "packages/server/src/config.ts",
  released("packages/server/src/config.ts"),
);
if (!config.DEFAULT_CONFIG) fail("config.ts no longer exports DEFAULT_CONFIG");
const tlsType = released("packages/server/src/config.ts").match(
  /export type TlsMode = ([^;]+);/,
);
if (!tlsType) fail("config.ts: `export type TlsMode = …;` marker not found");
const tlsModes = [...tlsType[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);

const identity = released("packages/server/src/api/identity.ts");
const caps = identity.match(/export const CAPABILITIES = \[([\s\S]*?)\]/);
const protocol = identity.match(/export const PROTOCOL_VERSION = (\d+);/);
if (!caps || !protocol)
  fail("api/identity.ts: CAPABILITIES / PROTOCOL_VERSION markers not found");
const capabilities = [...caps[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);

const nvmrc = released(".nvmrc").trim();
if (!/^\d+$/.test(nvmrc)) fail(".nvmrc must pin a major Node version");

// ---------------------------------------------------------------- markdown

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/<[^>]+>/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

const docSlugs = readdirSync(join(ROOT, "docs"))
  .filter((f) => f.endsWith(".md"))
  .map((f) => f.slice(0, -3));

/** Rewrite a link found in `fromDir` (repo-relative) for the website. */
function rewriteHref(href, fromDir) {
  if (/^([a-z]+:|#|\/)/i.test(href)) return href;
  const [path, hash] = href.split("#");
  const target = join(fromDir, path).replace(/\\/g, "/");
  const doc = target.match(/^docs\/([^/]+)\.md$/);
  if (doc && docSlugs.includes(doc[1]))
    return `${BASE}docs/${doc[1]}/${hash ? `#${hash}` : ""}`;
  const kind = /\.[a-z0-9]+$/i.test(target) ? "blob" : "tree";
  return `${REPO}/${kind}/main/${target}${hash ? `#${hash}` : ""}`;
}

function renderMarkdown(source, fromDir) {
  const headings = [];
  const marked = new Marked({
    gfm: true,
    renderer: {
      heading({ tokens, depth }) {
        const html = this.parser.parseInline(tokens);
        const id = slugify(html);
        if (depth === 2)
          headings.push({ id, text: html.replace(/<[^>]+>/g, "") });
        return `<h${depth} id="${id}">${html}</h${depth}>\n`;
      },
      link({ href, title, tokens }) {
        const text = this.parser.parseInline(tokens);
        const out = rewriteHref(href, fromDir);
        const external = /^https?:/.test(out);
        return `<a href="${out}"${title ? ` title="${title}"` : ""}${
          external ? ' rel="noopener"' : ""
        }>${text}</a>`;
      },
    },
  });
  return { html: marked.parse(source), headings };
}

/** Split `# Title` + first paragraph off a markdown document. */
function splitDoc(source, path) {
  const m = source.match(/^# (.+)\n+([\s\S]*)$/);
  if (!m) fail(`${path} must start with a "# Title" heading`);
  const title = m[1].trim();
  const body = m[2];
  const para = body
    .split(/\n\s*\n/)
    .find((p) => p.trim() && !/^(#|```|[-*|>]|\d+\.)/.test(p.trim()));
  if (!para) fail(`${path} needs an opening paragraph to use as its summary`);
  const summary = para
    .replace(/\s+/g, " ")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .replace(/[`*]/g, "")
    .trim();
  return { title, body, summary };
}

// Reading order for the sidebar; any new doc must be placed here.
const DOC_ORDER = [
  "getting-started",
  "home-hosting",
  "admin-console",
  "remote-app",
  "configuration",
  "security",
  "sharing",
  "testing",
  "architecture",
  "protocol",
  "troubleshooting",
];
for (const slug of docSlugs)
  if (!DOC_ORDER.includes(slug))
    fail(`docs/${slug}.md is not in DOC_ORDER — place it in the sidebar`);
for (const slug of DOC_ORDER)
  if (!docSlugs.includes(slug)) fail(`DOC_ORDER lists missing docs/${slug}.md`);

const docBodies = {};
const docs = DOC_ORDER.map((slug) => {
  const path = `docs/${slug}.md`;
  const { title, body, summary } = splitDoc(working(path), path);
  const { html, headings } = renderMarkdown(body, "docs");
  docBodies[slug] = html;
  // Full-text search index for the sidebar: the doc's distinct words.
  const terms = [
    ...new Set(
      body
        .toLowerCase()
        .replace(/```[\s\S]*?```/g, " ")
        .match(/[a-z0-9][a-z0-9-]{2,}/g) ?? [],
    ),
  ].join(" ");
  return {
    slug,
    title,
    summary,
    headings,
    terms,
    wordCount: body.split(/\s+/).filter(Boolean).length,
    published: firstPublished(path),
    modified: lastModified(path),
    source: `${REPO}/blob/main/${path}`,
  };
});

// ---------------------------------------------------------------- examples

const EXAMPLES = [
  { slug: "node-quickstart", file: "main.ts", lang: "ts" },
  { slug: "app-testing", file: "tests/medications_test.ts", lang: "ts" },
  { slug: "home-server", file: "compose.yaml", lang: "yaml" },
];
const examples = EXAMPLES.map(({ slug, file, lang }) => {
  const dir = `examples/${slug}`;
  const { title, summary } = splitDoc(working(`${dir}/README.md`), dir);
  return {
    slug,
    title,
    summary,
    file,
    lang,
    code: working(`${dir}/${file}`).trimEnd(),
    source: `${REPO}/tree/main/${dir}`,
  };
});

// ---------------------------------------------------------------- changelog

const changelog = released("CHANGELOG.md");
if (!/^## \[Unreleased\]/m.test(changelog))
  fail("CHANGELOG.md lost its `## [Unreleased]` heading");
const latest = changelog.match(
  /^## \[(\d+\.\d+\.\d+)\] - (\d{4}-\d{2}-\d{2})\n([\s\S]*?)(?=^## \[|(?![\s\S]))/m,
);

// ---------------------------------------------------------------- write

const data = {
  generatedFrom: tag ?? "working tree",
  version: serverPkg.version,
  license: serverPkg.license,
  node: nvmrc,
  repo: REPO,
  bin: spec.BIN,
  lastUpdated: git("log", "-1", "--format=%cI") || fail("no git history"),
  protocol: Number(protocol[1]),
  capabilities,
  tlsModes,
  defaults: {
    port: config.DEFAULT_CONFIG.listen.port,
    adminPort: config.DEFAULT_CONFIG.listen.adminPort,
    tls: config.DEFAULT_CONFIG.tls.mode,
    maxBodyBytes: config.DEFAULT_CONFIG.limits.maxBodyBytes,
  },
  commands,
  settings,
  docs,
  examples,
  release: latest
    ? {
        version: latest[1],
        date: latest[2],
        html: renderMarkdown(latest[3], ".").html,
      }
    : null,
};

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(
  OUT,
  [
    "// Generated by scripts/extract-source-data.mjs — do not edit.",
    'import type { DocBodies, SourceData } from "../types";',
    "",
    `export const source: SourceData = ${JSON.stringify(data, null, 2)};`,
    "",
    `export const docBodies: DocBodies = ${JSON.stringify(docBodies, null, 2)};`,
    "",
  ].join("\n"),
);
console.log(
  `extract-source-data: v${data.version} from ${data.generatedFrom}; ` +
    `${commands.length} commands, ${docs.length} docs, ${examples.length} examples`,
);
